"candidate_name":"David Alden","id":"a59353b5-a33c-4783-bc79-f55ad2e39745","primary_category_id":"eaae452b-5923-426d-8391-bafd5583efac","resume_number":20817,"source_hash":"e8868c67a54e339e0db8d70242a2556a","subcategory_id":null,"tags":[{"created_at":"2026-09-23T07:48:57.584084+00:00","id":"ccf7ff19-a2f5-4ae1-b3de-6f6697f18263","primary_category_id":"eaae452b-5923-426d-8391-bafd5583efac","resume_id":"a59353b5-a33c-4783-bc79-f55ad2e39745","sort_order":0,"subcategory_id":null},{"created_at":"2026-09-23T07:48:57.584084+00:00","id":"2a124779-5d9f-4189-ad86-ecaa7b94b244","primary_category_id":"15a0022e-8edc-4000-a3a2-e02726196f19","resume_id":"a59353b5-a33c-4783-bc79-f55ad2e39745","sort_order":1,"subcategory_id":"4bc9e26d-236a-4ff5-b2dd-59cc0a28ec4e"},{"created_at":"2026-09-23T07:48:57.584084+00:00","id":"bebc2a8b-6138-4ae1-993b-ad430bfed3bb","primary_category_id":"15a0022e-8edc-4000-a3a2-e02726196f19","resume_id":"a59353b5-a33c-4783-bc79-f55ad2e39745","sort_order":2,"subcategory_id":"3b124706-8495-4df3-8b27-5ab674f589ff"}],"updated_at":"2026-09-23 07:48:57.584084+00"}]$plan$::jsonb) loop
    select * into r from public.resumes where id=(p->>'id')::uuid;
    if not found or r.status<>'ACTIVE' or r.resume_type<>'ORIGINAL'
      or md5(coalesce(r.resume_text,'')||coalesce(r.structured_content::text,''))<>p->>'source_hash'
      or r.updated_at is distinct from (p->>'updated_at')::timestamptz then
      raise exception 'Resume changed since review: %',p->>'id';
    end if;
    select jsonb_agg(to_jsonb(s) order by s.sort_order,s.id) into current_tags from public.resume_tech_stacks s where s.resume_id=r.id;
    if current_tags is distinct from p->'tags' then raise exception 'Tags changed since review: %',r.id; end if;
    if not exists(select 1 from public.resume_tech_stacks where resume_id=r.id and primary_category_id=primary_id)
      or exists(select 1 from public.resume_tech_stacks where resume_id=r.id and subcategory_id=subtype_id) then
      raise exception 'Unexpected existing classification: %',r.id;
    end if;
    original_fields:=to_jsonb(r)-'subcategory_id'-'updated_at';
    if exists(select 1 from public.resume_tech_stacks where resume_id=r.id and primary_category_id=primary_id and subcategory_id is null) then
      update public.resume_tech_stacks set subcategory_id=subtype_id where resume_id=r.id and primary_category_id=primary_id and subcategory_id is null;
    else
      insert into public.resume_tech_stacks(resume_id,primary_category_id,subcategory_id,sort_order)
      select r.id,primary_id,subtype_id,coalesce(max(sort_order),-1)+1 from public.resume_tech_stacks where resume_id=r.id;
    end if;
    update public.resumes set subcategory_id=case when primary_category_id=primary_id and subcategory_id is null then subtype_id else subcategory_id end,
      updated_at=now() where id=r.id;
    if (select to_jsonb(x)-'subcategory_id'-'updated_at' from public.resumes x where id=r.id) is distinct from original_fields then
      raise exception 'Unexpected non-tag change: %',r.id;
    end if;
    if (select count(*) from public.resume_tech_stacks where resume_id=r.id)>12 then raise exception 'Too many tags: %',r.id; end if;
  end loop;
end $tagging$;
